code='''vocabulary = {1:'Ada',2:'AI',3:' ',4:'!',5:'🙂',6:'school',7:'book',8:'schoolbook'}

def encode(text):
    ids, position = [], 0
    while position < len(text):
        matches = [(i,piece) for i,piece in vocabulary.items() if text.startswith(piece,position)]
        if not matches:
            return ids, (position,text[position])
        token,piece = max(matches,key=lambda pair:len(pair[1]))
        ids.append(token)
        position += len(piece)
    return ids,None

for text in ['Ada!','AI🙂','schoolbook','school book','ada']:
    ids,error = encode(text)
    print(repr(text),ids,error)
    if error is None:
        assert ''.join(vocabulary[i] for i in ids)==text'''
